import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['hello_world_log_message_flow'],
        name: 'Hello World Log Message Flow',
        description: 'Hello World Log Message Flow Description',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['hello_world_log_message_flow_trigger'] },
        {
            email_conditions: 'checkpoint=',
            target_table: 'evaluation',
        }
    ),
    () => {}
)
